entries[142049] = { ["name"] = "Legacy of the Mountain King", ["text"] = "Karazhan\nConjured Item\nUnique\nUse: Break the seal of the book, granting you increased damage done and healing received when dropping below 25% health for 1 hour.\n\"The essence of this book is bound to Karazhan.\"" }
entries[142051] = { ["name"] = "Torment of the Worgen", ["text"] = "Karazhan\nConjured Item\nUnique\nUse: Break the seal on the book, granting you Torment of the Worgen. When striking an enemy that is below 30% health, you gain the Frenzy of the Worgen, increasing damage done by 15% for 30 sec. This effect cannot occur more than once every 5 minutes.\n\"The essence of this book is bound to Karazhan.\"" }
entries[142052] = { ["name"] = "Redemption of the Fallen", ["text"] = "Karazhan\nConjured Item\nUnique\nUse: Break the seal on the book, causing your heals on players below 25% health to summon a ghostly ally who will heal your party. This effect cannot occur more than once every 20 seconds.\n\"The essence of this book is bound to Karazhan.\"" }
