entries[142119] = { ["name"] = "Recipe: Potion of Prolonged Power", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Potion of Prolonged Power.\nMix a stack of 10 Potions of Prolonged Power at the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nSell Price:\nPotion of Prolonged Power\nUse: Drink to increase all stats by 88 for 1 min. (5 Min Cooldown)\nSell Price:\nRequires Blood of Sargeras , Crystal Vial (10)" }
entries[142120] = { ["name"] = "Recipe: Potion of Prolonged Power", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make a Potion of Prolonged Power.\nNo longer requires the Dalaran Alchemy Station.\nRequires Legion Alchemy (1)\nRequires The Nightfallen\n- Revered\nSell Price:\nPotion of Prolonged Power\nUse: Drink to increase all stats by 88 for 1 min. (5 Min Cooldown)\nSell Price:\nRequires Blood of Sargeras , Crystal Vial (10)" }
