entries[142157] = { ["name"] = "Aran's Relaxing Ruby", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nEquip: Your ranged attacks and spells have a chance to create a Flame Wreath beneath your target. After 6 sec, or if they move out of the ring, it explodes for [ 99 * (1 + Versatility)] Fire damage to all enemies within 12 yds.\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142158] = { ["name"] = "Faith's Crucible", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Launch 12 Holy Bolts at injured allies within 15 yds over 6 sec, healing for 18 per Bolt. (1 Min, 30 Sec Cooldown)\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142159] = { ["name"] = "Bloodstained Handkerchief", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\nUse: Garrote your target from behind, causing them to bleed for 4 Physical damage every 3 sec until they die. (1 Min Cooldown)\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142160] = { ["name"] = "Mrrgria's Favor", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nUse: Mark an enemy with a Thunder Ritual, dealing 69 Nature damage after 3 sec. If they are affected by Flame Gale, Thunder Ritual deals 30% increased damage and stuns for 3 sec. (30 Sec Cooldown)\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142161] = { ["name"] = "Inescapable Dread", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: Your attacks have a chance to summon an intangible presence to haunt your target, reducing their auto attack damage against you by up to 214 per strike for 12 sec.\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142162] = { ["name"] = "Fluctuating Energy", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nEquip: Your healing spells have a chance to cause Loose Mana to form nearby, lasting 30 sec. Contact with it restores 58 mana to you.\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142164] = { ["name"] = "Toe Knee's Promise", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Create a Flame Gale at an enemy's location, dealing ( 10 * 8) Fire damage over 8 sec. If Flame Gale strikes an enemy affected by Thunder Ritual, Flame Gale's damage is increased by 30%, and its radius by 50%. (1 Min Cooldown)\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142165] = { ["name"] = "Deteriorated Construct Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Intellect]\nEquip: Your ranged attacks and spells have a chance to release a ball of Volatile Energy that travels towards your target, dealing 28 damage to enemies it passes through.\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142166] = { ["name"] = "Ethereal Urn", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength or Intellect]\n+ 7 Mastery\nUse: Instantly remove all Fear effects. (3 Min Cooldown)\nSell Price:" }
entries[142167] = { ["name"] = "Eye of Command", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\nEquip: Your melee auto attacks increase your Critical Strike by 1 for 10 sec, stacking up to 10 times. This effect is reset if you auto attack a different target.\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142168] = { ["name"] = "Majordomo's Dinner Bell", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Stamina\nUse: Increase a random secondary stat by 39 for 15 sec. (1 Min, 30 Sec Cooldown)\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142169] = { ["name"] = "Raven Eidolon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Stamina\n+ 6 Mastery\nUse: Conjure a Guardian's Familiar to watch over up to 4 nearby allies for 20 sec. 50% of damage each ally takes is transferred to you, up to 52 total damage per target. (2 Min Cooldown)\n\"Marked with a raven silhouette.\"\nSell Price:" }
entries[142170] = { ["name"] = "Drape of Shame", ["text"] = "Binds when picked up\nBack\n3 Armor\n+3 [Agility or Strength or Intellect]\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Versatility\nEquip: Increases the healing of your critical healing effects by 3%.\nSell Price:" }
