entries[142208] = { ["name"] = "Essence of Wyrmtongue", ["text"] = "Quest Item\nUnique\nUse: Disguise yourself as a wyrmtongue for 10 min. (10 Sec Cooldown)\n\"Not for consumption... under normal circumstances.\"" }
