entries[142213] = { ["name"] = "Empowered Arcane Ward", ["text"] = "Quest Item\nUnique\nUse: Plants an Arcane Ward. (5 Sec Cooldown)\n\"The essence of magical energy surrounding the ward is far greater than one can imagine.\"" }
entries[142214] = { ["name"] = "7.1 Dungeon - Karazhan - Cloth SHOULDER 2", ["text"] = "Binds when picked up\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Haste\n+ 4 Mastery\nSell Price:" }
entries[142215] = { ["name"] = "Wine-Stained Mantle", ["text"] = "Binds when picked up\nBack\n3 Armor\n+3 [Agility or Strength or Intellect]\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Mastery\n\"A keepsake from one unforgettable night.\"\n\nBurden of Power (0/2)\nAmulet of the Last Guardian\nWine-Stained Mantle\n(2) Set : Killing a Legion dungeon boss increases your damage and healing by 10% for 2 min.\nSell Price:" }
entries[142216] = { ["name"] = "Nightborne Armaments", ["text"] = "Binds when picked up\nUnique\nUse: Place a crate of arms on the ground, enabling all Rebellious Citizens within 3 yards. (10 Sec Cooldown)" }
entries[142223] = { ["name"] = "Sun Darter Hatchling", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight click to summon and dismiss your Sun Darter Hatchling.\nRequires level 1 to 80 ( 80)" }
entries[142224] = { ["name"] = "Gift of the Holy Keepers", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires Journeyman Riding\n\"Teaches you how to summon a rideable watcher. This mount changes based on your specialization.\"" }
entries[142225] = { ["name"] = "Ban-lu, Grandmaster's Companion", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your companion Ban-Lu. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The child of Xuen, Ban-Lu has served each Grandmaster faithfully for many years.\"\nQuest:\nThe Trial of Ban-Lu" }
entries[142226] = { ["name"] = "Trust of a Fierce Wolfhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Huntmaster's Fierce Wolfhawk.\nSummons and dismisses your Huntmaster's Fierce Wolfhawk. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A jumble of talons and claws that can fly and swim. No one is safe.\"\nVendor:\nPan the Kind Hand\nZone:\nTrueshot Lodge" }
entries[142227] = { ["name"] = "Trust of a Loyal Wolfhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Huntmaster's Loyal Wolfhawk.\nSummons and dismisses your Huntmaster's Loyal Wolfhawk\nThis is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The spirit of the Great Hunter found you worthy, and now its children will answer your call forevermore.\"\nQuest:\nNight of the Wilds" }
entries[142228] = { ["name"] = "Trust of a Dire Wolfhawk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Huntmaster's Dire Wolfhawk.\nSummons and dismisses your Huntmaster's Dire Wolfhawk. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"If asked to fetch, will most likely bring you back the head of a small mammal or humanoid.\"\nVendor:\nPan the Kind Hand\nZone:\nTrueshot Lodge" }
entries[142231] = { ["name"] = "Decaying Reins of the Vilebrood Vanquisher", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Deathlord's Vilebrood Vanquisher.\nSummons and dismisses your Deathlord's Vilebrood Vanquisher. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A powerful red dragon raised in undeath by its own life energies, a true mockery of life.\"\nQuest:\nThe Lost Glacier" }
entries[142232] = { ["name"] = "Iron Reins of the Bloodthirsty War Wyrm", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Battlelord's Bloodthirsty War Wyrm.\nSummons and dismisses your Battlelord's Bloodthirsty War Wyrm. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Also responds to \"Mister Bitey.\"\"\nQuest:\nThe Trial of Rage" }
entries[142233] = { ["name"] = "Shadowy Reins of the Accursed Wrathsteed", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Netherlord's Accursed Wrathsteed.\nSummons and dismisses your Netherlord's Accursed Wrathsteed. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Shadow plus fire, what could go wrong?\"\nDrop:\nLord Hel'Nurath\nZone:\nBroken Shore" }
entries[142234] = { ["name"] = "Vicious War Bear", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vicious War Bear.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Almost twice as vicious as its Horde counterpart.\"\nVendor:\nNecrolord Sipe\nZone:\nStormwind City\nCost:\n1" }
entries[142235] = { ["name"] = "Vicious War Bear", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vicious War Bear.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Nearly twice as vicious as its Alliance counterpart.\"\nVendor:\nDeathguard Netharian\nZone:\nOrgrimmar\nCost:\n1" }
entries[142236] = { ["name"] = "Midnight's Eternal Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Midnight.\nSummons and dismisses Midnight.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"Still one of the most vicious steeds stabled in Karazhan.\"\nDrop:\nAttumen the Huntsman\nLocation:\nReturn to Karazhan" }
entries[142237] = { ["name"] = "Vicious War Lion", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vicious War Lion.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Many squires were harmed in the making of this mount.\"\nVendor:\nNecrolord Sipe\nZone:\nStormwind City\nCost:\n1" }
entries[142238] = { ["name"] = "Incredible Monsters and Where to Locate Them", ["text"] = "Quest Item\n\"A copy of this literature resides in almost every mage's sanctuary in Azeroth.\"" }
entries[142239] = { ["name"] = "Handbook of Feathery Friends", ["text"] = "Quest Item\n\"Small text on the cover reads that the word \"Friends\" is not to be taken literally.\"" }
entries[142240] = { ["name"] = "Draconic Compendium, Volume IV", ["text"] = "Quest Item\n\"Readers say that further iterations have gotten progressively worse.\"" }
entries[142241] = { ["name"] = "Unusual Crystal", ["text"] = "Quest Item\nUnique\n\"Etched with nightborne runes.\"" }
entries[142244] = { ["name"] = "Volatile Construct Core", ["text"] = "Quest Item\n\"Seething with energy.\"" }
entries[142245] = { ["name"] = "Charged Arcshaper Staff", ["text"] = "Quest Item\n\"The weapon crackles with latent energy.\"" }
entries[142246] = { ["name"] = "Broken Pocket Watch", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The watch is scratched and broken. Crumpled within appears to be a note.\"" }
entries[142247] = { ["name"] = "99.0 [reuse me]", ["text"] = "Quest Item" }
entries[142248] = { ["name"] = "Exquisitely Stinky Cheese", ["text"] = "Quest Item\n\"The odor is appalling.\"" }
entries[142249] = { ["name"] = "Falanaar Fine Vintage", ["text"] = "Quest Item\n\"A lovely drop.\"" }
entries[142250] = { ["name"] = "Aegwynn and the Dragon Hunt", ["text"] = "Binds when picked up\nDuration: 2 hrs (real time)\n\"Copy commissioned by Archmage Newhearth of the Curators. Do not worry about returning the book, it will return on its own.\"\n<Right Click to Read>" }
entries[142251] = { ["name"] = "Ly'leth's Missive", ["text"] = "Quest Item\n\"Even though it was written with great haste, Ly'leth's handwriting and prose are exquisite.\"\n<Right Click to Read>" }
entries[142258] = { ["name"] = "Book of Tactics", ["text"] = "Quest Item\n\"Written by the master tactician Lord Ravencrest himself.\"" }
entries[142259] = { ["name"] = "Spectral Feather", ["text"] = "Conjured Item\nUnique\nUse: Extend the duration of your Frayfeather Hatchling to 5 days." }
entries[142260] = { ["name"] = "Arcane Nullifier", ["text"] = "Quest Item\nUse: Remove the shielding from Arcshaper Thorendis.\n\"Specially attuned to nightborne energies.\"" }
entries[142261] = { ["name"] = "Fruit of the Arcan'dor", ["text"] = "Quest Item\n\"Cultivated with hope for redemption.\"" }
entries[142262] = { ["name"] = "Electrified Key", ["text"] = "Use: Activate an inactive arachnodrone. (10 Sec Cooldown)\n\"He had that in his pocket?\"\nSell Price:" }
entries[142263] = { ["name"] = "Machine Fluid", ["text"] = "Use: Coat your nearby pets and battle pets in oil for 1 hour. (10 Sec Cooldown)\n\"Keeps things nice and greasy.\"\nSell Price:" }
entries[142264] = { ["name"] = "Drudge Fluid", ["text"] = "Use: Inject your nearby pets or battle pets with drudge fluid for 1 hour. (10 Sec Cooldown)\n\"Are you sure you want to do that?\"\nSell Price:" }
entries[142265] = { ["name"] = "Big Red Raygun", ["text"] = "Binds when used\nToy\nUse: Make your nearby pets and battle pets huge, and red! (10 Min Cooldown)\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\"Probably harmless.\"\nSell Price:" }
entries[142266] = { ["name"] = "Handful of Gizmos", ["text"] = "Crafting Reagent\n\"Mechanical pets love gizmos.\"\nSell Price:" }
