entries[142361] = { ["name"] = "Ivory Talon", ["text"] = "Binds when picked up\nUnique\nUse: Heal 100% of maximum health and become an avenger of Aviana. While transformed, you are hostile to all players, and killing players grants Marks of Prey. Can only be used in falcosaur and PvP World Quest areas, and flags the user for PvP. (15 Min Cooldown)\n\"Holding this talon makes you yearn to grasp prey in your hands and rend it to pieces.\"\nSell Price:" }
entries[142363] = { ["name"] = "Mark of Prey", ["text"] = "Binds when picked up\nUse: Increases reputation with Talon's Vengeance by 100.\n\"Symbol of a successful hunt.\"" }
entries[142364] = { ["name"] = "Bag of Twigs", ["text"] = "Binds when picked up\nUnique (5)\nUse: Build a nest that allows resting and lasts for 5 min. If you spend at least 5 seconds resting you will become well-rested and gain 3% to all stats for 1 hour. Can only be used in Broken Isles. (5 Min Cooldown)\nRequires Talon's Vengeance\n- Friendly\nSell Price:" }
