entries[142383] = { ["name"] = "Plans: Darkspear", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Darkspear.\nRequires Classic Blacksmithing (1)\nSell Price:\nDarkspear\nBinds when equipped\nTwo-Hand Polearm\n6 - 13 Damage Speed 3.60\n(2.6 damage per second)\nDurability 100 / 100\nChance on hit: Party members have a chance to increase their critical strike by 17 . Lasts for 20 sec.\nSell Price:\nRequires Enchanted Thorium Bar (20), Powerful Mojo (20), Huge Emerald (2), Azerothian Diamond (2), Dense Grinding Stone (2)" }
entries[142384] = { ["name"] = "Depleted Nether Crystal", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"This runescribed crystal faintly pulses with remnants of dark energy.\"" }
entries[142385] = { ["name"] = "Stolen Enchanted Thorium Bar", ["text"] = "Quest Item\n\"Pilfered from the camps around Un'Goro, these bars should come in handy for any blacksmithing crafting.\"" }
entries[142386] = { ["name"] = "Mostly Powerful Mojo", ["text"] = "Quest Item\n\"This is equal in power to powful mojo... mostly.\"" }
entries[142387] = { ["name"] = "Calcified Diemetradon Scale", ["text"] = "Quest Item\n\"Can replace a huge emerald in a pinch.\"" }
entries[142388] = { ["name"] = "Bleached Stegodon Spike", ["text"] = "Quest Item\n\"White like a diamond, and nearly as hard.\"" }
entries[142389] = { ["name"] = "Broken Darkspear", ["text"] = "Quest Item\nUse: Break the Darkspear down, gaining knowledge of what was used to craft it." }
entries[142392] = { ["name"] = "Thief's Instructions", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"This hastily scrawled note speaks of stealing the Focusing Iris.\"\n<Right Click to Read>" }
entries[142393] = { ["name"] = "Fel Crystal", ["text"] = "Quest Item\n\"Radiating with fel energy.\"" }
entries[142394] = { ["name"] = "\"Ancient\" Elven War Orders", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"At first it looks like authentic orders to destroy an enemy outpost, but it oozes fel magic and is newer.\"" }
entries[142395] = { ["name"] = "Fel-Infused Totem Fragment", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Part of a tauren totem, dripping with fel energy. It can only have come from Highmountain.\"" }
entries[142396] = { ["name"] = "Damaged Kirin Tor Insignia", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Engraved with the name \"Levia Laurence\"\"" }
entries[142397] = { ["name"] = "Gilded Scroll Case", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The markings on the case appear to be vrykul runes.\"" }
entries[142398] = { ["name"] = "Darkwater Skate", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. Can only be summoned in aquatic environments.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Little is known about this elusive species of ray, found only in the dark waters surrounding Darkmoon Island.\"\nVendor:\nGalissa Sundew\nZone:\nDarkmoon Island" }
entries[142399] = { ["name"] = "Experimental Targeting Orb", ["text"] = "Quest Item\nUnique\nUse: Command your Withered to test their resistance against the potency of fel magic. (5 Sec Cooldown)" }
