entries[142401] = { ["name"] = "Telemancy Orbs", ["text"] = "Unique\nUse: Hurl a Telemancy Orb at target location, spawning Hungering Withered. Only works in the Noble District of Suramar City. (45 Sec Cooldown)\n\"A squad of withered, delivered in an instant.\"" }
entries[142402] = { ["name"] = "Plans: Light Earthforged Blade", ["text"] = "Use: Teaches you how to make a Light Earthforged Blade.\nRequires Classic Blacksmithing (1)\nSell Price:\nLight Earthforged Blade\nBinds when picked up\nOne-Hand Sword\n3 - 6 Damage Speed 2.60\n(1.7 damage per second)\n+2 Strength\n+3 Stamina\n+ 5 Critical Strike\nDurability 90 / 90\nSell Price:\nRequires Mithril Bar (12), Core of Earth (4)\nOptional Reagents: Optional Reagent Slot (#31)" }
entries[142403] = { ["name"] = "Brawler's Burly Basilisk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The spikes on this beast can pierce plate armor with ease -- only the most elite riders can even consider mounting this deadly pincushion.\"\nVendor:\nQuackenbush\nZone:\nDeeprun Tram\nCost:\n\nVendor:\nPaul North\nZone:\nBrawl'gar Arena\nCost:" }
entries[142405] = { ["name"] = "Advanced Telemancy Beacon", ["text"] = "Quest Item\nUse: Survey the Terrace of Order. Masquerade disguise will fail. (15 Sec Cooldown)" }
entries[142406] = { ["name"] = "Drums of the Mountain", ["text"] = "Drums of the Mountain\nUse: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min.\n\nDoes not does affect allies above level 50. (2 Min Cooldown)\nSell Price:" }
entries[142407] = { ["name"] = "Pattern: Drums of the Mountain", ["text"] = "Binds when picked up\nUse: Teaches you how to make Drums of the Mountain.\nCraft Drums of the Mountain.\nRequires Legion Leatherworking (1)\nSell Price:\nDrums of the Mountain\nUse: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min.\n\nDoes not does affect allies above level 50. (2 Min Cooldown)\nSell Price:\nRequires Stonehide Leather (10), Unbroken Claw (5), Unbroken Tooth (5)" }
entries[142408] = { ["name"] = "Pattern: Drums of the Mountain", ["text"] = "Binds when picked up\nUse: Teaches you how to make Drums of the Mountain.\nReduces the materials required to craft Drums of the Mountain.\nRequires Legion Leatherworking (1)\nRequires Highmountain Tribe\n- Revered\nSell Price:\nDrums of the Mountain\nUse: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min.\n\nDoes not does affect allies above level 50. (2 Min Cooldown)\nSell Price:\nRequires Stonehide Leather (8), Unbroken Claw (3), Unbroken Tooth (3)" }
entries[142409] = { ["name"] = "Pattern: Drums of the Mountain", ["text"] = "Binds when picked up\nUse: Teaches you how to make Drums of the Mountain.\nSignificantly reduces the materials required to craft Drums of the Mountain.\nRequires Legion Leatherworking (1)\nRequires Highmountain Tribe\n- Exalted\nSell Price:\nDrums of the Mountain\nUse: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min.\n\nDoes not does affect allies above level 50. (2 Min Cooldown)\nSell Price:\nRequires Stonehide Leather (5), Unbroken Claw (2), Unbroken Tooth (2)" }
