entries[142436] = { ["name"] = "Arcanist's Manasaber", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses your Arcanist's Manasaber .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Nightfallen\n- Exalted\n\n\"Upon her return to The Nighthold, First Arcanist Thalyssra saw to it that adventurers who helped her liberate Suramar were rewarded with prized mounts from the royal stable.Summoning this mount in Suramar City will also apply Masquerade.\"\nQuest:\nFate of the Nightborne\nZone:\nSuramar" }
entries[142437] = { ["name"] = "Vicious War Scorpion", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vicious War Scorpion.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Has very few non-pointy ends.\"\nVendor:\nDeathguard Netharian\nZone:\nOrgrimmar\nCost:\n1" }
